590	    #[test]
591	    fn run_until_returns_at_readiness_despite_requeuing_main_work() {
592	        const REQUEUE_LIMIT: usize = 10_000;
593	
594	        let dispatcher = Arc::new(ThreadedDispatcher::new());
595	        let foreground = ForegroundExecutor::new(dispatcher.clone());
596	
597	        // Mirrors main-thread work that yields and immediately re-queues
598	        // itself (e.g. an idle-time sweep): the main queue never drains until
599	        // such work finishes every iteration, so readiness must be observed
600	        // between runnables rather than only at quiescence.
601	        let iterations = Arc::new(AtomicUsize::new(0));
602	        foreground
603	            .spawn({
604	                let iterations = iterations.clone();
605	                async move {
606	                    for _ in 0..REQUEUE_LIMIT {
607	                        iterations.fetch_add(1, Ordering::SeqCst);
608	                        yield_once().await;
609	                    }
610	                }
611	            })
612	            .detach();
613	
614	        let completed = Arc::new(AtomicBool::new(false));
615	        foreground
616	            .spawn({
617	                let completed = completed.clone();
618	                async move {
619	                    completed.store(true, Ordering::SeqCst);
620	                }
621	            })
622	            .detach();
623	
624	        dispatcher.run_until(|| completed.load(Ordering::SeqCst).then_some(()));
625	        assert!(
626	            iterations.load(Ordering::SeqCst) < REQUEUE_LIMIT,
627	            "run_until should return at readiness instead of draining re-queued main work"
628	        );
