35	impl PlatformScheduler {
36	    pub fn new(dispatcher: Arc<dyn PlatformDispatcher>) -> Self {
37	        Self {
38	            dispatcher: dispatcher.clone(),
39	            clock: Arc::new(PlatformClock { dispatcher }),
40	            next_session_id: AtomicU16::new(0),
41	            #[cfg(feature = "profiler")]
42	            foreground_runnables: crate::profiler::journal::foreground_runnable_counter(),
43	        }
44	    }
