46	    pub fn foreground_executor(self: &Arc<Self>) -> LocalExecutor {
47	        let session_id = self.next_session_id();
48	        let scheduler = Arc::downgrade(self);
49	        LocalExecutor::new(session_id, self.clone(), move |runnable| {
50	            if let Some(scheduler) = scheduler.upgrade() {
51	                scheduler.schedule_local(session_id, runnable);
52	            }
53	        })
54	    }
