69	    fn block(
70	        &self,
71	        _session_id: Option<SessionId>,
72	        #[cfg_attr(target_family = "wasm", allow(unused_mut))] mut future: Pin<
73	            &mut dyn Future<Output = ()>,
74	        >,
75	        #[cfg_attr(target_family = "wasm", allow(unused_variables))] timeout: Option<Duration>,
76	    ) -> bool {
77	        #[cfg(target_family = "wasm")]
78	        {
79	            let _ = (&future, &timeout);
80	            panic!("Cannot block on wasm")
81	        }
82	        #[cfg(not(target_family = "wasm"))]
83	        {
84	            use waker_fn::waker_fn;
85	            let deadline = timeout.map(|t| Instant::now() + t);
86	            let parker = parking::Parker::new();
87	            let unparker = parker.unparker();
88	            let waker = waker_fn(move || {
89	                unparker.unpark();
90	            });
91	            let mut cx = Context::from_waker(&waker);
92	            if let Poll::Ready(()) = future.as_mut().poll(&mut cx) {
93	                return true;
94	            }
95	
96	            let park_deadline = |deadline: Instant| {
97	                // Timer expirations are only delivered every ~15.6 milliseconds by default on Windows.
98	                // We increase the resolution during this wait so that short timeouts stay reasonably short.
99	                let _timer_guard = self.dispatcher.increase_timer_resolution();
100	                parker.park_deadline(deadline)
101	            };
102	
103	            loop {
104	                match deadline {
105	                    Some(deadline) if !park_deadline(deadline) && deadline <= Instant::now() => {
106	                        return false;
107	                    }
108	                    Some(_) => (),
109	                    None => parker.park(),
110	                }
111	                if let Poll::Ready(()) = future.as_mut().poll(&mut cx) {
112	                    break true;
113	                }
114	            }
115	        }
116	    }
