118	    fn schedule_local(&self, _session_id: SessionId, runnable: Runnable<RunnableMeta>) {
119	        #[cfg(feature = "profiler")]
120	        self.foreground_runnables.queued();
121	        self.dispatcher
122	            .dispatch_on_main_thread(runnable, Priority::default());
123	    }
