302	    fn spawn_dedicated_dropping_task_cancels_future() {
303	        use parking_lot::Mutex;
304	        use std::sync::mpsc;
305	
306	        let background =
307	            BackgroundExecutor::new(Arc::new(PlatformScheduler::new(Arc::new(SmokeDispatcher))));
308	
309	        let (started_tx, started_rx) = mpsc::channel::<()>();
310	        let (after_park_tx, after_park_rx) = mpsc::channel::<()>();
311	        let observed_post_await_write = Arc::new(Mutex::new(false));
