352	    #[test]
353	    fn spawn_dedicated_thread_tears_down_after_work_completes() {
354	        use std::sync::mpsc;
355	
356	        // Fires from `Drop` so we observe teardown of the dedicated future's
357	        // captured state on whichever thread runs its destructor.
358	        struct DropSignal {
359	            tx: Option<mpsc::Sender<std::thread::ThreadId>>,
360	        }
361	        impl Drop for DropSignal {
362	            fn drop(&mut self) {
363	                if let Some(tx) = self.tx.take() {
364	                    let _ = tx.send(std::thread::current().id());
365	                }
366	            }
367	        }
368	
369	        let background =
370	            BackgroundExecutor::new(Arc::new(PlatformScheduler::new(Arc::new(SmokeDispatcher))));
371	        let (started_tx, started_rx) = mpsc::channel::<std::thread::ThreadId>();
372	        let (drop_tx, drop_rx) = mpsc::channel::<std::thread::ThreadId>();
373	
374	        let task = background.spawn_dedicated(move |_executor| async move {
375	            // Captured by the future's state. When the future completes and
376	            // its state is dropped on the dedicated thread, this guard's
377	            // `Drop` fires and reports the thread id it ran on.
378	            let _guard = DropSignal { tx: Some(drop_tx) };
379	            started_tx
380	                .send(std::thread::current().id())
381	                .expect("started signal must be received");
382	            // Future returns immediately. The dedicated thread should then
383	            // drop the future (firing _guard), exit the recv loop, and exit.
384	        });
385	
386	        let dedicated_thread_id = started_rx
387	            .recv_timeout(Duration::from_secs(2))
388	            .expect("dedicated future failed to start");
389	        assert_ne!(
390	            dedicated_thread_id,
391	            std::thread::current().id(),
392	            "dedicated future ran on the test thread"
393	        );
394	
395	        // Drive the root task to completion so its body finishes.
396	        futures::executor::block_on(task);
397	
398	        // The guard's drop runs from the dedicated thread as it tears down
399	        // the future's captured state. If the executor/recv-loop were
400	        // keeping the future alive past task completion, this would hang.
401	        let drop_thread_id = drop_rx
402	            .recv_timeout(Duration::from_secs(2))
403	            .expect("dedicated future's captured state was not dropped after task completion");
404	        assert_eq!(
405	            drop_thread_id, dedicated_thread_id,
406	            "dedicated future's captured state must be dropped on the dedicated thread, not elsewhere"
407	        );
408	    }
